void Monstey_Profiles(){const auto constraints=Monstey_Row("C/R/A",3,100,200);const std::string source="C/R/A=42\n";Monstey::Monstey_FearUnpackedOwnedOptions options;options.arena_budget_bytes=1024*1024;options.callback_opaque_word=0xFFFFFFFF;options.insert_opaque_word=0x80000000;auto image=Monstey::Monstey_FearLoadUnpackedOwned(std::span(reinterpret_cast<const std::uint8_t*>(source.data()),source.size()),constraints,options);Monstey_Check(image.profile.at("callback_opaque_word").as_uint()==0xFFFFFFFF&&image.profile.at("insert_opaque_word").as_uint()==0x80000000,"explicit raw opaque options");Monstey_Check(image.profile.at("statistics").at("validation_false_results_ignored_by_native_callback").as_uint()==1,"concrete false validation counted and ignored");const auto value=Monstey::Monstey_FearInspectUnpackedOwned(image,Monstey_Values()).at("items").at(0);Monstey_Check(value.at("runtime_word_u32").as_uint()==42,"invalidated value not silently dropped");++Monstey_cases;
 const auto saved=_mm_getcsr();for(unsigned rounding=0;rounding<4;++rounding)for(unsigned flush=0;flush<4;++flush){const auto mode=0x1F80u|(rounding<<13)|((flush&1)?0x8000u:0u)|((flush&2)?0x40u:0u)|0x21u;_mm_setcsr(mode);auto scalar=Monstey_One(2,"1.5");Monstey_Check(_mm_getcsr()==mode,"load restores complete caller MXCSR");auto report=Monstey::Monstey_FearInspectUnpackedOwned(scalar,Monstey_Values());Monstey_Check(_mm_getcsr()==mode&&report.at("items").at(0).at("runtime_word_u32").as_uint()==0x3FC00000,"query profile numeric bits and MXCSR restoration");auto q=Monstey_Values();q.limit=0;Monstey_Error([&]{(void)Monstey::Monstey_FearInspectUnpackedOwned(scalar,q);},"unpacked_query_arguments");Monstey_Check(_mm_getcsr()==mode,"throw restores caller MXCSR");++Monstey_cases;}_mm_setcsr(saved);
 {auto raw=Monstey_Row("C/R/A",3);for(std::size_t n=1;n<raw.size();++n){const auto partial=std::span(raw).first(n);Monstey_Error([&]{(void)Monstey::Monstey_FearLoadUnpackedOwned(std::span(reinterpret_cast<const std::uint8_t*>(source.data()),source.size()),partial,options);},"unpacked_open_returned_null");}}
}
void Monstey_PipelineEdges(){
 {auto constraints=Monstey_Row("C/R/A",3);auto other=Monstey_Row("C/R/B",7);constraints.insert(constraints.end(),other.begin(),other.end());const std::string text="C/R/A=1\nC/R/B=3,bad\n";Monstey::Monstey_FearUnpackedOwnedOptions options;options.arena_budget_bytes=1024*1024;auto image=Monstey::Monstey_FearLoadUnpackedOwned(std::span(reinterpret_cast<const std::uint8_t*>(text.data()),text.size()),constraints,options);auto q=Monstey_Values();q.attribute=1;const auto v=Monstey::Monstey_FearInspectUnpackedOwned(image,q).at("items").at(0).at("components");Monstey_Check(v.at(0).at("bits_u32").as_uint()==0x40400000&&v.at(1).at("bits_u32").as_uint()==0&&v.at(2).at("bits_u32").as_uint()==0,"later partial vector inherits actual native strncpy padding");++Monstey_cases;}
 {auto image=Monstey_One(6," ");const auto v=Monstey::Monstey_FearInspectUnpackedOwned(image,Monstey_Values()).at("items").at(0).at("components");Monstey_Check(v.at(0).at("bits_u32").as_uint()==0xCDCDCDCD&&v.at(1).at("bits_u32").as_uint()==0xCDCDCDCD,"sscanf EOF leaves first vector destination pattern");++Monstey_cases;}
 {auto image=Monstey_One(3,"1;;2;");const auto nodes=Monstey_Nodes(image);Monstey_Check(Monstey::Monstey_FearDbValueCount(image.Memory(),nodes[2])==3,"empty middle token retained");const auto values=Monstey_Raw(image,nodes[2]+12);Monstey_Check(Monstey_Raw(image,values)==1&&Monstey_Raw(image,values+4)==0&&Monstey_Raw(image,values+8)==2,"numeric-only empty middle token conversion");++Monstey_cases;}
 Monstey_Error([&]{(void)Monstey_One(3,"");},"unpacked_primitive_failure");
 {auto image=Monstey_One(3,"42","/R/A");Monstey_Check(image.root_allocation_bytes==20&&image.table_counts==std::array<Monstey_U32,3>{0,0,0}&&Monstey_Raw(image,image.root+8)==0&&Monstey_Raw(image,image.root+16)==1,"native C0/A1 route publishes empty root and retains it");Monstey_Options q;q.summary=true;Monstey_Check(Monstey::Monstey_FearInspectUnpackedOwned(image,q).at("totals").at("categories").as_uint()==0,"empty category route inspected without repair");++Monstey_cases;}
 {auto image=Monstey_One(3,"42","C//A");Monstey_Check(image.table_counts==std::array<Monstey_U32,3>{1,0,1},"empty record native sizing table quirk");Monstey_Options q;q.summary=true;Monstey_Error([&]{(void)Monstey::Monstey_FearInspectUnpackedOwned(image,q);},"unpacked_graph_layout");}
 {auto image=Monstey_One(3,"42","C/A");const auto n=Monstey_Nodes(image);Monstey_Check(Monstey_Text(image,Monstey::Monstey_FearDbNodeName(image.Memory(),n[0]))=="C/A"&&Monstey_Text(image,Monstey::Monstey_FearDbNodeName(image.Memory(),n[1]))=="C"&&Monstey_Text(image,Monstey::Monstey_FearDbNodeName(image.Memory(),n[2]))=="A","one-slash native split semantics");++Monstey_cases;}
 {auto image=Monstey_One(3,"42","C/R/");const auto n=Monstey_Nodes(image);Monstey_Check(Monstey_Text(image,Monstey::Monstey_FearDbNodeName(image.Memory(),n[2])).empty(),"empty attribute name retained");++Monstey_cases;}
 {auto constraints=Monstey_Row(std::string("C/R/A\0suffix",12),3);const std::string text="C/R/A=17\n";auto image=Monstey::Monstey_FearLoadUnpackedOwned(std::span(reinterpret_cast<const std::uint8_t*>(text.data()),text.size()),constraints);Monstey_Check(Monstey::Monstey_FearInspectUnpackedOwned(image,Monstey_Values()).at("items").at(0).at("runtime_word_u32").as_uint()==17,"constraint complete read followed by first NUL logical key");++Monstey_cases;}
 {auto image=Monstey_One(1,"true");Monstey_Check(Monstey::Monstey_FearInspectUnpackedOwned(image,Monstey_Values()).at("items").at(0).at("runtime_word_u32").as_uint()==0,"native bool numeric conversion does not invent text booleans");++Monstey_cases;}
 {const auto constraints=Monstey_Row("C/R/A",4);std::string text="C/R/A=stable\n";auto bytes=std::vector<std::uint8_t>(text.begin(),text.end());auto image=Monstey::Monstey_FearLoadUnpackedOwned(bytes,constraints);std::fill(bytes.begin(),bytes.end(),std::uint8_t{0});Monstey_Check(Monstey::Monstey_FearInspectUnpackedOwned(image,Monstey_Values()).at("items").at(0).at("string").at("bytes_hex").as_string()=="737461626c65","output owns storage after input mutation");++Monstey_cases;}
 {auto constraints=Monstey_Row("A/R/A",3);auto row=Monstey_Row("B/R/A",3);constraints.insert(constraints.end(),row.begin(),row.end());const std::string text="A/R/A=1\nB/R/A=2\n";auto image=Monstey::Monstey_FearLoadUnpackedOwned(std::span(reinterpret_cast<const std::uint8_t*>(text.data()),text.size()),constraints);auto m=image.Memory();const auto c0=Monstey::Monstey_FearDbChildByIndex(m,image.root,0),c1=Monstey::Monstey_FearDbChildByIndex(m,image.root,1),record=Monstey::Monstey_FearDbChildByIndex(m,c0,0),attr=Monstey::Monstey_FearDbAttributeByIndex(m,record,0);Monstey_Store(image,c1+12,record);Monstey_Store(image,attr+10,9,1);Monstey_Store(image,Monstey_Raw(image,attr+12),record);const auto matches=Monstey::Monstey_FearInspectUnpackedOwned(image,Monstey_Values()).at("items").at(0).at("matching_traversed_ordinals");Monstey_Check(matches.size()==2&&matches.at(0).at("category").as_uint()==0&&matches.at(1).at("category").as_uint()==1,"direct aliased reference retains every traversed ordinal association");++Monstey_cases;}
}

