int wmain(int argc,wchar_t**argv){try{if(argc!=4)throw std::runtime_error("expected.json relative-base NEW-report");Monstey_PreSourceGraph(argv[1],argv[2]);Monstey_DirectViews();Monstey_Profiles();Monstey_PipelineEdges();const auto report=Monstey_Json::object({{"status","PASS"},{"cases",Monstey_cases},{"checks",Monstey_checks},{"expected_faults",Monstey_faults},{"native_original_entrypoint_invoked",false},{"direct_image_cases_separate_from_load",true}});Monstey::Monstey_WriteNewText(argv[3],report.dump(2)+"\n");std::cout<<report.dump()<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
